-- The Identifiers & registration spine card for Croatia, Malaysia,
-- Poland and Romania. GENERATED by tools/identifier-cards.mjs -- re-run
-- the tool rather than editing this file. Card content, researched from
-- primary sources, is in tools/data/identifier-cards.json.
--
-- Croatia and Malaysia were already at the framework's five-card
-- ceiling, so the new card displaces one. Nothing is dropped without
-- its rows moving: Croatia's "Signatures" rows are appended to
-- "Format & standard", Malaysia's "Peppol as a separate track" rows
-- are appended to the new card.

-- ---- Poland: 4 -> 5 cards ----
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 4 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'en', 'Identifiers & registration', '[["The identifier","The NIP, and it is a condition of using KSeF at all rather than merely a field on the invoice. EU VAT numbers appear cross-border; organisational units carry an internal IDWew."],["Authentication, not registration","There is no register to join. Access is by Trusted Profile, qualified signature, qualified seal, a token, or — from 1 February 2026 — a KSeF certificate issued through the Certificates and Permissions Module."],["The step most summaries omit","A non-natural person whose qualified seal does not carry its NIP must file form ZAW-FA to designate its first authorised person. That is a large share of companies, and it is a genuine precondition."],["No vendor accreditation","Nothing certifies software; the Ministry refers only to commercial applications integrated with the API. The KSeF certificate is issued to TAXPAYERS for authentication and offline invoicing — vendor pages that read it as a software certification are wrong."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Poland') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', 'Identificadores y registro', '[["El identificador","El NIP, y es condición para usar KSeF en absoluto, no un mero campo de la factura. Los números de IVA de la UE aparecen en operaciones transfronterizas; las unidades organizativas llevan un IDWew interno."],["Autenticación, no registro","No hay registro al que adherirse. El acceso es por Perfil de Confianza, firma cualificada, sello cualificado, un token o —desde el 1 de febrero de 2026— un certificado KSeF emitido por el Módulo de Certificados y Permisos."],["El paso que casi nadie menciona","Una persona jurídica cuyo sello cualificado no lleve su NIP debe presentar el formulario ZAW-FA para designar a su primera persona autorizada. Afecta a muchas empresas y es un requisito previo real."],["Sin acreditación de proveedores","Nada certifica el software; el Ministerio solo menciona aplicaciones comerciales integradas con la API. El certificado KSeF se emite a los CONTRIBUYENTES para autenticarse y facturar sin conexión, no a los proveedores."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Poland') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', 'Kennungen und Registrierung', '[["Die Kennung","Die NIP, und sie ist Voraussetzung für die Nutzung von KSeF überhaupt, nicht bloss ein Rechnungsfeld. Grenzüberschreitend erscheinen EU-USt-IdNrn.; Organisationseinheiten führen eine interne IDWew."],["Authentifizierung, keine Registrierung","Ein Register zum Beitreten gibt es nicht. Der Zugang erfolgt über das Vertrauensprofil, eine qualifizierte Signatur, ein qualifiziertes Siegel, ein Token oder — ab dem 1. Februar 2026 — ein KSeF-Zertifikat aus dem Zertifikats- und Berechtigungsmodul."],["Der Schritt, den die meisten Zusammenfassungen auslassen","Eine juristische Person, deren qualifiziertes Siegel ihre NIP nicht trägt, muss das Formular ZAW-FA einreichen, um ihre erste berechtigte Person zu benennen. Das betrifft viele Unternehmen und ist eine echte Voraussetzung."],["Keine Anbieterakkreditierung","Nichts zertifiziert Software; das Ministerium nennt nur kommerzielle Anwendungen mit API-Anbindung. Das KSeF-Zertifikat wird an STEUERPFLICHTIGE für Authentifizierung und Offline-Fakturierung ausgegeben, nicht an Anbieter."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Poland') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', 'Identifiants et enregistrement', '[["L''identifiant","Le NIP, et c''est une condition pour utiliser KSeF, non un simple champ de la facture. Les numéros de TVA de l''UE apparaissent en transfrontalier ; les unités organisationnelles portent un IDWew interne."],["Authentification, non inscription","Il n''existe pas de registre à rejoindre. L''accès se fait par Profil de confiance, signature qualifiée, cachet qualifié, jeton ou — depuis le 1er février 2026 — un certificat KSeF délivré par le module de certificats et d''habilitations."],["L''étape que la plupart des résumés omettent","Une personne morale dont le cachet qualifié ne porte pas son NIP doit déposer le formulaire ZAW-FA pour désigner sa première personne habilitée. Cela vise beaucoup d''entreprises et constitue un préalable réel."],["Aucun agrément d''éditeur","Rien ne certifie les logiciels ; le ministère ne mentionne que des applications commerciales raccordées à l''API. Le certificat KSeF est délivré aux CONTRIBUABLES pour l''authentification et la facturation hors ligne, non aux éditeurs."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Poland') AND d.section = 'file_format' AND d.sort_order = 4;

