INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'en', 'Identifiers & registration', '[["The identifier","The CIF or CUI. Where a customer has no tax identification code at all, the recipient identifier is thirteen zero digits — a rule worth knowing before a validation rejects the file."],["SPV enrolment is a precondition","A business must be registered in the Spatiul Privat Virtual before it can transmit. It is independently compulsory for legal persons anyway, under the Fiscal Procedure Code since 1 March 2022."],["Where that requirement is NOT","It is not in OUG 120/2021. We read the ordinance in full and it never mentions the SPV; the requirement sits in the implementing procedure, OMF 1365/2021. A great many summaries cite the ordinance."],["No accreditation","OUG 120/2021 establishes no approval or vetting of private software or service providers, and ANAF publishes no register of them."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Romania') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', 'Identificadores y registro', '[["El identificador","El CIF o CUI. Cuando el cliente no tiene código de identificación fiscal alguno, el identificador del destinatario son trece ceros: conviene saberlo antes de que una validación rechace el fichero."],["La inscripción en el SPV es requisito previo","La empresa debe estar registrada en el Spatiul Privat Virtual para poder transmitir. Además es obligatoria de por sí para las personas jurídicas, según el Código de Procedimiento Fiscal, desde el 1 de marzo de 2022."],["Dónde NO está ese requisito","No está en la OUG 120/2021. Leímos la ordenanza completa y no menciona el SPV; el requisito está en el procedimiento de desarrollo, la OMF 1365/2021. Muchísimos resúmenes citan la ordenanza."],["Sin acreditación","La OUG 120/2021 no establece aprobación ni verificación de programas o proveedores privados, y ANAF no publica registro alguno de ellos."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Romania') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', 'Kennungen und Registrierung', '[["Die Kennung","Die CIF oder CUI. Hat ein Kunde überhaupt keine Steueridentifikationsnummer, ist die Empfängerkennung dreizehnmal die Ziffer null — gut zu wissen, bevor eine Validierung die Datei zurückweist."],["Die SPV-Eintragung ist Voraussetzung","Ein Unternehmen muss im Spatiul Privat Virtual registriert sein, um übermitteln zu können. Für juristische Personen ist sie ohnehin seit dem 1. März 2022 nach der Steuerverfahrensordnung zwingend."],["Wo diese Anforderung NICHT steht","Nicht in der OUG 120/2021. Wir haben die Verordnung vollständig gelesen; das SPV kommt darin nicht vor. Die Anforderung steht in der Durchführungsprozedur OMF 1365/2021. Sehr viele Zusammenfassungen zitieren die Verordnung."],["Keine Akkreditierung","Die OUG 120/2021 sieht keine Zulassung oder Prüfung privater Software oder Dienstleister vor, und ANAF veröffentlicht kein Verzeichnis."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Romania') AND d.section = 'file_format' AND d.sort_order = 4;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', 'Identifiants et enregistrement', '[["L''identifiant","Le CIF ou CUI. Lorsqu''un client n''a aucun code d''identification fiscale, l''identifiant du destinataire est treize zéros — utile à savoir avant qu''une validation ne rejette le fichier."],["L''inscription au SPV est un préalable","Une entreprise doit être enregistrée au Spatiul Privat Virtual pour pouvoir transmettre. Elle est de toute façon obligatoire pour les personnes morales depuis le 1er mars 2022, en vertu du Code de procédure fiscale."],["Où cette exigence ne figure PAS","Pas dans l''OUG 120/2021. Nous avons lu l''ordonnance en entier et le SPV n''y apparaît jamais ; l''exigence se trouve dans la procédure d''application, l''OMF 1365/2021. Quantité de résumés citent l''ordonnance."],["Aucun agrément","L''OUG 120/2021 n''institue ni approbation ni contrôle des logiciels ou prestataires privés, et l''ANAF ne publie aucun registre."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Romania') AND d.section = 'file_format' AND d.sort_order = 4;

