UPDATE deep_dive_card_translations SET rows_json = '[["Basissyntax","UBL 2.1 XML"],["Europäische Ausrichtung","EN 16931-1:2017"],["Nationale CIUS","HR-FISK 2.0"],["Peppol-Kompatibilität","Unterstützt Peppol BIS 3.0 als gemeinsames Format"],["SOAP-Umschlag","Immer mit qualifiziertem Zertifikat signiert"],["Die Rechnungs-XML selbst","Signatur optional, aber gängige Praxis"]]' WHERE lang = 'de' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Croatia' AND d.section = 'file_format' AND d.sort_order = 0);
UPDATE deep_dive_card_translations SET rows_json = '[["Syntaxe de base","XML UBL 2.1"],["Alignement européen","EN 16931-1:2017"],["CIUS nationale","HR-FISK 2.0"],["Compatibilité Peppol","Prend en charge Peppol BIS 3.0 comme format commun"],["Enveloppe SOAP","Toujours signée avec un certificat qualifié"],["Le XML de la facture lui-même","Signature facultative, mais pratique courante"]]' WHERE lang = 'fr' AND card_id = (SELECT d.id FROM deep_dive_cards d JOIN countries c ON c.id = d.country_id WHERE c.name_en = 'Croatia' AND d.section = 'file_format' AND d.sort_order = 0);
