INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'en', 'Identifiers & registration', '[["The identifier","The OIB, carried as Peppol scheme 9934. Note the value is the bare eleven-digit OIB, not HR followed by it, despite the scheme being labelled Croatia VAT number."],["It is not \"Peppol-based\"","Croatia borrows Peppol''s identifier scheme and an AS4 profile but exchanges over a NATIONAL network, with its own address metadata service run by the Tax Administration. That changes who you can route through."],["The enrolment step","Authorise an information intermediary — or your own access point — through FiskAplikacija, reached via ePorezna, and record the authorisations there. There is no separate e-invoicing registration beyond it."],["Intermediaries ARE accredited, and listed","An intermediary needs a compliance confirmation from the Tax Administration, which requires testing, documentation review and ISO/IEC 27001. The Tax Administration publishes the register of them."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Croatia') AND d.section = 'file_format' AND d.sort_order = 5;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', 'Identificadores y registro', '[["El identificador","El OIB, transportado como esquema Peppol 9934. El valor es el OIB de once dígitos a secas, no HR seguido de él, pese a que el esquema se rotule como número de IVA croata."],["No está «basado en Peppol»","Croacia toma prestado el esquema de identificadores de Peppol y un perfil AS4, pero intercambia por una red NACIONAL, con su propio servicio de metadatos de direcciones gestionado por la Administración Tributaria."],["El paso de alta","Autorice a un intermediario de información —o su propio punto de acceso— mediante FiskAplikacija, a la que se accede por ePorezna, y registre allí las autorizaciones. No hay un alta de facturación electrónica aparte."],["Los intermediarios SÍ se acreditan, y hay lista","Un intermediario necesita una confirmación de conformidad de la Administración Tributaria, con pruebas, revisión documental e ISO/IEC 27001. La Administración publica el registro."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Croatia') AND d.section = 'file_format' AND d.sort_order = 5;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', 'Kennungen und Registrierung', '[["Die Kennung","Die OIB, übermittelt als Peppol-Schema 9934. Der Wert ist die blosse elfstellige OIB, nicht HR mit nachgestellter Nummer, obwohl das Schema als kroatische USt-IdNr. bezeichnet ist."],["Es ist nicht «Peppol-basiert»","Kroatien übernimmt Peppols Kennungsschema und ein AS4-Profil, tauscht aber über ein NATIONALES Netz aus, mit einem eigenen Adressmetadatendienst der Steuerverwaltung. Das ändert, über wen Sie routen können."],["Der Anmeldeschritt","Bevollmächtigen Sie einen Informationsvermittler — oder Ihren eigenen Access Point — über FiskAplikacija, erreichbar via ePorezna, und hinterlegen Sie die Berechtigungen dort. Eine gesonderte E-Rechnungsregistrierung gibt es nicht."],["Vermittler WERDEN akkreditiert, und sind gelistet","Ein Vermittler braucht eine Konformitätsbestätigung der Steuerverwaltung, mit Tests, Dokumentenprüfung und ISO/IEC 27001. Die Verwaltung veröffentlicht das Verzeichnis."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Croatia') AND d.section = 'file_format' AND d.sort_order = 5;
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', 'Identifiants et enregistrement', '[["L''identifiant","L''OIB, porté par le schéma Peppol 9934. La valeur est l''OIB à onze chiffres seul, non précédé de HR, bien que le schéma soit intitulé numéro de TVA croate."],["Ce n''est pas « fondé sur Peppol »","La Croatie emprunte le schéma d''identifiants de Peppol et un profil AS4, mais échange sur un réseau NATIONAL, doté de son propre service de métadonnées d''adresses géré par l''administration fiscale."],["L''étape d''inscription","Habilitez un intermédiaire d''information — ou votre propre point d''accès — via FiskAplikacija, accessible par ePorezna, et enregistrez-y les habilitations. Il n''existe pas d''inscription distincte à la facturation électronique."],["Les intermédiaires SONT agréés, et listés","Un intermédiaire doit obtenir une confirmation de conformité de l''administration fiscale, avec tests, examen documentaire et ISO/IEC 27001. L''administration publie le registre."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE name_en = 'Croatia') AND d.section = 'file_format' AND d.sort_order = 5;

